inline const SOI *GetSOI(const void *buf) {
  return ::flatbuffers::GetRoot<SOI>(buf);
}

inline const SOI *GetSizePrefixedSOI(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SOI>(buf);
}

inline const char *SOIIdentifier() {
  return "$SOI";
}

inline bool SOIBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SOIIdentifier());
}

inline bool SizePrefixedSOIBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SOIIdentifier(), true);
}

template <bool B = false>
inline bool VerifySOIBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SOI>(SOIIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSOIBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SOI>(SOIIdentifier());
}

inline void FinishSOIBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SOI> root) {
  fbb.Finish(root, SOIIdentifier());
}

inline void FinishSizePrefixedSOIBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SOI> root) {
  fbb.FinishSizePrefixed(root, SOIIdentifier());
}

inline std::unique_ptr<SOIT> UnPackSOI(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SOIT>(GetSOI(buf)->UnPack(res));
}

inline std::unique_ptr<SOIT> UnPackSizePrefixedSOI(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SOIT>(GetSizePrefixedSOI(buf)->UnPack(res));
}

#endif  // FLATBUFFERS_GENERATED_SOI_MAIN_H_
